1	type Item = { type: string; material?: string; cursed?: boolean; enchantment?: number };
2	
3	const enchantmentLevel = (item: Item): number => item.enchantment ?? 0;
4	
5	const basePremiumsByType: Record<string, number> = { sword: 100, amulet: 60, staff: 80, potion: 40, rune: 25, moonstone: 25 };
6	
7	const BLOCK_SIZE = 3;
8	const BLOCK_PREMIUM = 60;
9	
10	const sumBy = <T>(values: T[], valueOf: (value: T) => number): number =>
11	  values.reduce((sum, value) => sum + valueOf(value), 0);
12	
13	const basePremiumForItem = (item: Item): number => basePremiumsByType[item.type];
14	
15	const sumOfItemBasePremiums = (items: Item[]): number =>
16	  sumBy(items, basePremiumForItem);
17	
18	const groupByType = (items: Item[]): Item[][] => {
19	  const groups = new Map<string, Item[]>();
20	  for (const item of items) {
21	    const group = groups.get(item.type) ?? [];
22	    group.push(item);
23	    groups.set(item.type, group);
24	  }
25	  return [...groups.values()];
26	};
27	
28	const basePremiumForGroup = (group: Item[]): number =>
29	  group.length === BLOCK_SIZE ? BLOCK_PREMIUM : sumOfItemBasePremiums(group);
30	
31	export const basePremium = (items: Item[]): number =>
32	  sumBy(groupByType(items), basePremiumForGroup);
33	
34	const PROCESSING_FEE = 5;
35	
36	type Customer = { yearsWithMHPCO: number };
37	type QuoteStep = { op: "quote"; items: Item[] };
38	type Damage = { itemType: string; amount: number };
39	type ClaimStep = { op: "claim"; policy: number; incident: { cause: string; damages: Damage[] } };
40	type Step = QuoteStep | ClaimStep;
41	type Scenario = { customer: Customer; steps: Step[] };
42	
43	type QuoteResult = { premium: number };
44	type ClaimResult = { payout: number; remainingCap: number };
45	type StepResult = QuoteResult | ClaimResult;
46	
47	const CURSE_SURCHARGE_RATE = 0.5;
48	const HIGH_ENCHANTMENT_RATE = 0.3;
49	const HIGH_ENCHANTMENT_THRESHOLD = 5;
50	const FIRST_INSURANCE_RATE = 0.1;
51	const LOYALTY_RATE = 0.2;
52	const LOYALTY_THRESHOLD = 2;
53	const FOLLOWUP_RATE = 0.15;
54	
55	const surchargeOf = (item: Item, rate: number): number => basePremiumForItem(item) * rate;
56	
57	const curseSurchargeForItem = (item: Item): number =>
58	  item.cursed ? surchargeOf(item, CURSE_SURCHARGE_RATE) : 0;
59	
60	const curseSurcharge = (items: Item[]): number =>
61	  sumBy(items, curseSurchargeForItem);
62	
63	const highEnchantmentSurchargeForItem = (item: Item): number =>
64	  enchantmentLevel(item) >= HIGH_ENCHANTMENT_THRESHOLD
65	    ? surchargeOf(item, HIGH_ENCHANTMENT_RATE)
66	    : 0;
67	
68	const highEnchantmentSurcharge = (items: Item[]): number =>
69	  sumBy(items, highEnchantmentSurchargeForItem);
70	
71	const rateOfPolicyBase = (policyBase: number, rate: number): number => policyBase * rate;
72	
73	const firstInsuranceSurcharge = (policyBase: number): number =>
74	  rateOfPolicyBase(policyBase, FIRST_INSURANCE_RATE);
75	
76	const loyaltyDiscount = (policyBase: number, customer: Customer): number =>
77	  customer.yearsWithMHPCO >= LOYALTY_THRESHOLD ? rateOfPolicyBase(policyBase, LOYALTY_RATE) : 0;
78	
79	const followUpDiscount = (policyBase: number, isFollowUp: boolean): number =>
80	  isFollowUp ? rateOfPolicyBase(policyBase, FOLLOWUP_RATE) : 0;
81	
82	const itemSurcharges = (items: Item[]): number =>
83	  curseSurcharge(items) + highEnchantmentSurcharge(items);
84	
85	// The premium is rounded up so any fraction lands in MHPCO's favor.
86	const roundPremiumInFavorOfMHPCO = (premium: number): number => Math.ceil(premium);
87	
88	const quotePremium = (step: QuoteStep, customer: Customer, isFollowUp: boolean): number => {
89	  const policyBase = basePremium(step.items);
90	  const surcharges = itemSurcharges(step.items) + firstInsuranceSurcharge(policyBase);
91	  const discounts = loyaltyDiscount(policyBase, customer) + followUpDiscount(policyBase, isFollowUp);
92	  return roundPremiumInFavorOfMHPCO(policyBase + surcharges - discounts + PROCESSING_FEE);
93	};
94	
95	const DEDUCTIBLE = 100;
96	const CAP_MULTIPLIER = 2;
97	const REDUCED_REIMBURSEMENT_THRESHOLD = 8;
98	const REDUCED_REIMBURSEMENT_RATE = 0.5;
99	
100	const insuranceValuesByType: Record<string, number> = { sword: 1000, amulet: 600, staff: 800, potion: 400, rune: 250, moonstone: 250 };
101	
102	const insuranceValue = (item: Item): number => insuranceValuesByType[item.type];
103	
104	const insuranceSum = (items: Item[]): number =>
105	  sumBy(items, insuranceValue);
106	
107	const reimbursableValueBeforeDeductible = (damageAmount: number, item: Item): number =>
108	  enchantmentLevel(item) >= REDUCED_REIMBURSEMENT_THRESHOLD
109	    ? damageAmount * REDUCED_REIMBURSEMENT_RATE
110	    : damageAmount;
111	
112	const damagedItem = (damage: Damage, items: Item[]): Item =>
113	  items.find((item) => item.type === damage.itemType) as Item;
114	
115	const payoutForDamage = (damage: Damage, items: Item[]): number =>
116	  reimbursableValueBeforeDeductible(damage.amount, damagedItem(damage, items)) - DEDUCTIBLE;
117	
118	const claimResult = (step: ClaimStep, scenario: Scenario): ClaimResult => {
119	  const policy = scenario.steps[step.policy] as QuoteStep;
120	  const cap = insuranceSum(policy.items) * CAP_MULTIPLIER;
121	  const payout = sumBy(step.incident.damages, (damage) => payoutForDamage(damage, policy.items));
122	  return { payout, remainingCap: cap - payout };
123	};
124	
125	export const runScenario = (scenario: Scenario): { results: StepResult[] } => ({
126	  results: scenario.steps.map((step, index) =>
127	    step.op === "quote"
128	      ? { premium: quotePremium(step, scenario.customer, index > 0) }
129	      : claimResult(step, scenario),
130	  ),
131	});
