const payoutForDamage = (damage: Damage, items: Item[]): number =>
  reimbursableValueBeforeDeductible(damage.amount, damagedItem(damage, items)) - DEDUCTIBLE;

// The deductible in payoutForDamage applies once per damage entry, so the
// incident payout is simply the sum across every damage in the incident.
const incidentPayout = (damages: Damage[], items: Item[]): number =>
  sumBy(damages, (damage) => payoutForDamage(damage, items));

const claimResult = (step: ClaimStep, scenario: Scenario): ClaimResult => {
  const policy = scenario.steps[step.policy] as QuoteStep;
  const cap = insuranceSum(policy.items) * CAP_MULTIPLIER;
  const payout = incidentPayout(step.incident.damages, policy.items);
  return { payout, remainingCap: cap - payout };
};
